import{_ as n,o as t,c as a,ah as r}from"./chunks/framework.C-FRNfAJ.js";const d=JSON.parse('{"title":"Inscriptions et conventions","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/coordinateur/inscriptions.md","filePath":"src/guide/coordinateur/inscriptions.md"}'),s={name:"guide/coordinateur/inscriptions.md"};function o(i,e,l,u,c,p){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="inscriptions-et-conventions" tabindex="-1">Inscriptions et conventions <a class="header-anchor" href="#inscriptions-et-conventions" aria-label="Permalink to &quot;Inscriptions et conventions&quot;">​</a></h1><p><strong>Parcours → Inscriptions</strong> liste les apprenants admis, avec leur programme, leur cohorte, leur format, leur statut et leurs consentements. Filtrez par statut (À signer, Actives, Suspendues, Abandons, Terminées), par programme, ou sur <strong>Sans cohorte</strong>.</p><h2 id="placer-un-apprenant" tabindex="-1">Placer un apprenant <a class="header-anchor" href="#placer-un-apprenant" aria-label="Permalink to &quot;Placer un apprenant&quot;">​</a></h2><p>Une inscription <strong>sans cohorte</strong> (le conseiller n&#39;en a pas choisi à l&#39;admission, ou la cohorte a été annulée) porte le repère « À placer ». <strong>Placer</strong> ouvre la liste des cohortes qui peuvent l&#39;accueillir : pas encore démarrées, avec une place et un prix pour son format. L&#39;apprenant est prévenu par e-mail. <strong>Déplacer</strong> fait de même pour un apprenant déjà placé, tant qu&#39;il n&#39;a pas signé.</p><p>Toute inscription non abandonnée <strong>occupe une place</strong>. L&#39;effectif et la zone de rentabilité ne comptent que les inscriptions <strong>signées</strong>.</p><h2 id="le-financement" tabindex="-1">Le financement <a class="header-anchor" href="#le-financement" aria-label="Permalink to &quot;Le financement&quot;">​</a></h2><p>Avant la signature, <strong>Financement</strong> permet de désigner un <strong>financeur</strong> (un compte organisation au rôle Financeur) et sa part, de 1 à 100 %. « Aucun » laisse l&#39;apprenant payer l&#39;intégralité. La répartition figure sur la convention. Voir <a href="./../entreprises/financeur.html">Financer des apprenants</a>.</p><h2 id="l-apporteur-d-affaires" tabindex="-1">L&#39;apporteur d&#39;affaires <a class="header-anchor" href="#l-apporteur-d-affaires" aria-label="Permalink to &quot;L&#39;apporteur d&#39;affaires&quot;">​</a></h2><p><strong>Apporteur d&#39;affaires</strong> associe l&#39;inscription au compte qui l&#39;a apportée, s&#39;il y en a un. Le code (<code>AP-XXXXXX</code>) est normalement saisi par le candidat ; vous pouvez le corriger <strong>jusqu&#39;au premier paiement</strong>. L&#39;apporteur touche 5 % de chaque encaissement (voir <a href="./remunerations.html">Rémunérations et commissions</a>).</p><h2 id="le-texte-de-la-convention" tabindex="-1">Le texte de la convention <a class="header-anchor" href="#le-texte-de-la-convention" aria-label="Permalink to &quot;Le texte de la convention&quot;">​</a></h2><p>Depuis <strong>Inscriptions</strong>, le <strong>texte de la convention</strong> (les conditions générales) se publie en <strong>versions immuables</strong> : une fois publiée, une version ne se modifie plus. Une nouvelle version vaut pour les signatures <strong>suivantes</strong> ; chaque convention signée garde celle qu&#39;elle a signée. <strong>Sans texte publié, aucune convention ne peut être signée.</strong></p><p>Kura ajoute à ce texte les conditions particulières (parties, programme, cohorte, format, prix hors taxe, échéancier 30/40/30).</p><h2 id="la-contre-signature" tabindex="-1">La contre-signature <a class="header-anchor" href="#la-contre-signature" aria-label="Permalink to &quot;La contre-signature&quot;">​</a></h2><p>Quand l&#39;apprenant a signé, edPage group doit contre-signer. L&#39;Administrateur règle si la contre-signature est <strong>automatique</strong> (au nom du représentant, par défaut) ou <strong>manuelle</strong>. En mode manuel, les conventions à contre-signer apparaissent dans les inscriptions, filtrables par <strong>À contre-signer</strong>, avec le bouton <strong>Contre-signer</strong>.</p><p>À la contre-signature : la convention reçoit sa référence <code>CONV-NB-AAAA-XXX</code> et son PDF scellé, partis à l&#39;apprenant ; l&#39;inscription devient <strong>active</strong> ; le format, la cohorte et le prix sont figés ; la première facture est émise.</p><h3 id="la-convention-tripartite" tabindex="-1">La convention tripartite <a class="header-anchor" href="#la-convention-tripartite" aria-label="Permalink to &quot;La convention tripartite&quot;">​</a></h3><p>Quand une convention avec financeur est contre-signée, Kura prépare la <strong>convention tripartite</strong>. Le financeur la signe ; en mode manuel, vous la contre-signez avec <strong>Contre-signer la tripartite</strong>. Elle ne bloque ni l&#39;inscription ni la facturation.</p><h2 id="la-convention-de-stage" tabindex="-1">La convention de stage <a class="header-anchor" href="#la-convention-de-stage" aria-label="Permalink to &quot;La convention de stage&quot;">​</a></h2><p>Pour un apprenant dont la formation comporte un stage, <strong>Saisir le stage</strong> (puis <strong>Modifier le stage</strong>) demande :</p><ul><li>l&#39;<strong>entreprise d&#39;accueil</strong> et son <strong>contact signataire</strong> (nom et e-mail) ;</li><li>le <strong>Coach-Tuteur</strong> qui encadre le stage, choisi parmi ceux de la cohorte ;</li><li>les <strong>dates</strong> de début et de fin, et la <strong>mission</strong>.</li></ul><p><strong>Envoyer la convention de stage en signature</strong> lance les signatures : l&#39;apprenant (ou son représentant légal s&#39;il est mineur) et l&#39;entreprise, par lien et code. Tant qu&#39;<strong>aucune signature</strong> n&#39;est donnée, vous pouvez modifier le stage ; <strong>toute modification retire la convention envoyée</strong> et il faut l&#39;envoyer de nouveau. Quand les deux parties ont signé, edPage contre-signe (<strong>Contre-signer le stage</strong> en mode manuel).</p><p>Le nom de l&#39;entreprise est repris dans l&#39;évaluation du stage par le jury. Un stage sans convention reste possible : le jury saisit alors l&#39;entreprise à la main.</p><h2 id="changer-de-cohorte-force-majeure" tabindex="-1">Changer de cohorte (force majeure) <a class="header-anchor" href="#changer-de-cohorte-force-majeure" aria-label="Permalink to &quot;Changer de cohorte (force majeure)&quot;">​</a></h2><p><strong>Changer de cohorte (force majeure)</strong> déplace un apprenant sur justificatif : saisissez le <strong>motif et le justificatif</strong> (par exemple « certificat médical du 12 mars »). Il passe à la session suivante du même programme, ses paiements sont conservés (le reste dû des factures émises est annulé par un avoir, puis refacturé sur la nouvelle convention en déduisant ce qui est déjà payé) et aucune attestation partielle n&#39;est délivrée.</p><p>Après la signature, tout changement de cohorte <strong>remplace la convention</strong> : l&#39;ancienne est conservée, l&#39;inscription repasse en attente de signature, et une nouvelle convention, au même prix et au même format, est à signer. L&#39;apprenant est prévenu.</p><h2 id="enregistrer-un-abandon" tabindex="-1">Enregistrer un abandon <a class="header-anchor" href="#enregistrer-un-abandon" aria-label="Permalink to &quot;Enregistrer un abandon&quot;">​</a></h2><p><strong>Enregistrer un abandon</strong> met fin à l&#39;inscription. Choisissez le motif :</p><ul><li><strong>Abandon volontaire</strong> ;</li><li><strong>Désinscription pour impayé</strong> (après J+30, faute de régularisation).</li></ul><p>Une note est facultative. La place est libérée et l&#39;apprenant sort de l&#39;effectif. Aucun avoir n&#39;est émis : les tranches non encore facturées ne le seront plus, les factures déjà émises restent dues. Si au moins un bloc est validé, vous pouvez délivrer une <strong>attestation partielle</strong> (voir <a href="./resultats.html#l-attestation-partielle">Résultats et certification</a>).</p><h2 id="les-consentements" tabindex="-1">Les consentements <a class="header-anchor" href="#les-consentements" aria-label="Permalink to &quot;Les consentements&quot;">​</a></h2><p>La colonne <strong>Consentements</strong> montre la réponse de chaque apprenant : « Réutilisation » et « Image », ou « En attente ». Les deux sont requises avant la signature. Un apprenant <strong>mineur</strong> est signalé : ses consentements et sa signature sont ceux de son représentant légal.</p>',31)])])}const m=n(s,[["render",o]]);export{d as __pageData,m as default};
